// Compact, bundled copies of completed seasons, generated by
// scripts/snapshot.ts in GitHub Actions (where ESPN is reachable without CORS
// limits). A full season of games fits in ~100 KB instead of ~45 MB of raw
// team schedules.
import type { SeasonHighsResult } from './live';
import type { Conference, Game, LeaderTable, TeamRef, TeamStatTable } from './types';

/** [id, date, homeId, awayId, homeScore, awayScore, note, broadcasts] */
export type CompactGame = [string, string, string, string, number | null, number | null, string | null, string | null];

export interface SeasonSnapshot {
  year: number;
  generatedAt: string;
  teams: TeamRef[];
  standings: Conference[];
  games: Record<string, CompactGame[]>;
  /** Keyed `${seasonType}:${sort}`. */
  leaders: Record<string, LeaderTable>;
  teamStats: Record<string, TeamStatTable | null>;
  highs: Record<string, SeasonHighsResult | null>;
}

export function compactGame(g: Game): CompactGame {
  return [g.id, g.date, g.home.team.id, g.away.team.id, g.home.score ?? null, g.away.score ?? null, g.note ?? null, g.broadcasts.join(', ') || null];
}

export function expandGame(c: CompactGame, teams: Map<string, TeamRef>): Game {
  const [id, date, homeId, awayId, hs, as, note, tv] = c;
  const final = hs != null && as != null;
  const unknown = (tid: string): TeamRef => ({ id: tid, name: tid, shortName: tid, abbr: tid });
  const side = (tid: string, homeAway: 'home' | 'away', score: number | null, other: number | null) => ({
    team: teams.get(tid) ?? unknown(tid),
    homeAway,
    score: score ?? undefined,
    winner: final ? score! > other! : undefined,
    linescores: [],
    leaders: [],
  });
  return {
    id,
    date,
    state: final ? 'post' : 'pre',
    statusDetail: final ? 'Final' : '',
    home: side(homeId, 'home', hs, as),
    away: side(awayId, 'away', as, hs),
    broadcasts: tv ? tv.split(', ') : [],
    note: note ?? undefined,
  };
}
